cypress_script:
describe('Todo List CRUD Operations', () => {
  it('should add a new todo', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('input[data-testid="text-input"]').type('New Todo{enter}');
    cy.get('ul[data-testid="todo-list"]').children().should('have.length', 1);
  });
  it('should not add an empty todo', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('input[data-testid="text-input"]').type('{enter}');
    cy.get('ul[data-testid="todo-list"]').children().should('have.length', 0);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Todo List CRUD Operations', () => {
  test('should add a new todo', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('input[data-testid="text-input"]', 'New Todo');
    await page.press('input[data-testid="text-input"]', 'Enter');
    const todoList = await page.locator('ul[data-testid="todo-list"]').locator('li');
    expect(await todoList.count()).toBe(1);
  });
  test('should not add an empty todo', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.press('input[data-testid="text-input"]', 'Enter');
    const todoList = await page.locator('ul[data-testid="todo-list"]').locator('li');
    expect(await todoList.count()).toBe(0);
  });
});
